import java.util.*; public class InsertNodeAtEnd { public static class ListNode { int val; ListNode next; ListNode(int val) { this.val = val; this.next = null; } } public ListNode insertAtEnd(ListNode head, int val) { ListNode newNode = new ListNode(val); if (head == null) { return newNode; } ListNode current = head; while (current.next != null) { current = current.next; } current.next = newNode; return head; } }
